* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
.wo-wrap {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  overflow: auto;
  background: #1E293B;
  border: 1px solid #334155;
  border-radius: 6px;
  font-family: system-ui;
}
.wo-hint { padding: 8px 14px; font-size: 12px; color: #94A3B8; border-bottom: 1px solid #334155; }
table.wo { border-collapse: collapse; width: max-content; min-width: 100%; background: #1E293B; }
table.wo th { padding: 10px 14px; font-size: 12px; font-weight: 700; color: #F1F5F9; white-space: nowrap; text-align: left; border-bottom: 2px solid #475569; background: #334155; position: sticky; top: 0; }
table.wo td { padding: 8px 14px; font-size: 12px; color: #E2E8F0; border-bottom: 1px solid #334155; vertical-align: top; }
table.wo td.num { text-align: right; white-space: nowrap; }
table.wo td.nowrap { white-space: nowrap; }
table.wo td.warning { min-width: 360px; max-width: 560px; }
table.wo a { color: #93c5fd; text-decoration: underline; cursor: pointer; }
.empty { padding: 20px; color: #94A3B8; text-align: center; font-family: system-ui; }

srcDoc.js:
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
var NUM={'Days Late':1,'Days of Service':1};
function render(model){
  var root=document.getElementById('root'); if(!root) return;
  var rows=(model&&model.rows)||[];
  if(!rows.length){ root.innerHTML='<div class="empty">No data available</div>'; return; }
  var cols=Object.keys(rows[0]);
  var h='<table class="wo"><thead><tr>';
  cols.forEach(function(c){ h+='<th>'+esc(c)+'</th>'; });
  h+='</tr></thead><tbody>';
  rows.forEach(function(r){
    h+='<tr>';
    cols.forEach(function(c){ h+='<td class="'+(NUM[c]?'num':'nowrap')+'">'+esc(r[c])+'</td>'; });
    h+='</tr>';
  });
  h+='</tbody></table>';
  root.innerHTML=h;
}
appsmith.onReady(function(){ render(appsmith.model); appsmith.onModelChange(function(m){ render(m); }); });

